required <- c("readr", "dplyr")
if (length(required[!vapply(required, requireNamespace, logical(1), quietly=TRUE)])) stop("Install readr and dplyr.")
library(readr); library(dplyr)
root <- getwd()
runtime_root <- Sys.getenv("PAPER3_RUNTIME_DIR")
if (!nzchar(runtime_root) || !dir.exists(runtime_root)) stop("Set PAPER3_RUNTIME_DIR to the completed restricted runtime directory.")
benchmark_196 <- read_csv(file.path(root, "reference_outputs/PAPER_3_DESCRIPTIVE_REPRODUCTION_COMPARISON.csv"), show_col_types=FALSE)
rerun_196 <- read_csv(file.path(runtime_root, "phase_ii_descriptive_measurement_audit/outputs/PAPER_3_DESCRIPTIVE_REPRODUCTION_COMPARISON.csv"), show_col_types=FALSE)
if (nrow(benchmark_196) != 196 || nrow(rerun_196) != 196) stop("Expected 196 grouped checks.")
if (!all(rerun_196$within_tolerance)) stop("A raw-source grouped check failed.")
benchmark_desc <- read_csv(file.path(root, "reference_outputs/PAPER_3_PHASE_III_VALIDATED_DESCRIPTIVE_TABLES.csv"), show_col_types=FALSE)
rerun_desc <- read_csv(file.path(runtime_root, "phase_iii_controlled_descriptive_interpretation/outputs/PAPER_3_PHASE_III_VALIDATED_DESCRIPTIVE_TABLES.csv"), show_col_types=FALSE)
key <- c("table_id","metric","wave","domain","category")
joined <- inner_join(benchmark_desc, rerun_desc, by=key, suffix=c("_benchmark","_rerun"))
if (nrow(joined) != 153 || any(abs(joined$estimate_benchmark - joined$estimate_rerun) > 1e-10)) stop("Released descriptive benchmark check failed.")
benchmark_figure <- read_csv(file.path(root, "reference_outputs/PAPER_3_PHASE_IVB_ARRANGEMENT_TASK_FIGURE_DATA.csv"), show_col_types=FALSE)
rerun_figure <- read_csv(file.path(runtime_root, "phase_ivb_release_clearance/outputs/PAPER_3_PHASE_IVB_ARRANGEMENT_TASK_FIGURE_DATA.csv"), show_col_types=FALSE)
fig <- inner_join(benchmark_figure, rerun_figure, by=c("wave","worker_arrangement","task"), suffix=c("_benchmark","_rerun"))
if (nrow(fig) != 24 || any(abs(fig$estimate_benchmark - fig$estimate_rerun) > 1e-10)) stop("Figure 1 benchmark check failed.")
message("PASS: 196 grouped checks, 153 descriptive results, and 24 Figure 1 cells.")
